import unittest
import api

class IndependentBehavior(unittest.TestCase):
    def test_left(self): self.assertTrue(api.contains(-3,8,-3))
    def test_right(self): self.assertTrue(api.contains(-3,8,8))
    def test_single(self): self.assertTrue(api.contains(4,4,4))
    def test_outside(self): self.assertFalse(api.contains(-3,8,-4))
    def test_inside(self): self.assertTrue(api.contains(-3,8,0))
    def test_helper(self): self.assertEqual(api.interval_width(2,9),7)
